initialLayout.source:
const nes = await useSoundChip("nes");
setBpm(120);

// Follow the selected sound on the next note, using physical channels.
liveLoop("melody", async () => {
  const source = (await nes.getState()).preset.source;
  const channel = {pulse: CH1, triangle: CH3, noise: CH4, dmc: CH5, fds: CH6}[source];
  await nes.noteOn(channel, choose(scale("E3", "minorPentatonic", 2)));
  await beat(0.5);
  await nes.noteOff(channel);
  await beat(0.25);
});

returnedLayout.source:
// @ts-check
const nes = await useSoundChip('nes');
const phrase=nes.build(b=>{b.pulse.setVoice(CH1,{volume:8});b.noteOn(CH1,'C4');b.atSample(441).noise.noteOn();b.noise.noteOff();});
const snapshot=await nes.captureState();
console.table(await nes.compile(phrase,{initialState:snapshot}));
await nes.schedule(phrase,{name:'apu',repeatSeconds:1});
await nes.pulse.setVoice(CH1, {duty: 0.25, volume: 8, envelope: {period: 2, loop: true}});
await nes.pulse.setFrequency(CH1, 220);
await nes.noteOn(CH1, 'A3');
await nes.pulse.noteOn(CH2, 'C4');
await nes.triangle.noteOn('E4');
await nes.noise.setVoice({volume: 4, period: 6, shortMode: false});
await nes.noteOn(CH4, 'C4');
await nes.dmc.loadSample(new Uint8Array(257).fill(0xaa));
await nes.dmc.play({rate: 15, loop: true, level: 64});
await nes.noteOn(CH5, 'C4');
await nes.fds.setWave(Array.from({length: 64}, (_, i) => i));
await nes.fds.setVolume(16);
await nes.fds.setModulation({table: Array(32).fill(0), rate: 256, depth: 16, enabled: true});
await nes.noteOn(CH6, 'A3');
await nes.noteOff(CH1);
await nes.keyOff(CH2);
const state = await nes.getState();
context.marker = state.registers[0];
context.source = state.preset.source;
context.sweep = state.preset.pulse.sweep.shift;
const prepared = await livePrepare('voice', async api => {
  const voice = await api.useSoundChip('nes');
  return {voice, count: 0};
});
prepared.count += 1;
liveLoop('phrase', async () => {
  await nes.pulse.noteOn(CH1, choose(scale('C4', 'minor')));
  await beat(0.5);
  await nes.pulse.noteOff(CH1);
  await beat(0.25);
});
liveFx('gain', {context: {gain: 0.5}, process(input, output, state, ctx) {
  for (let i = 0; i < output[0].length; i++) output[0][i] = input[0][i] * ctx.gain;
}});
pg.log('ready', prepared.count);

